    @Test
    public void testIntegrateTwoBodyProblemForward() throws Exception {
        // Test integration of a simplified two-body problem (conservation of energy)
        // d^2x/dt^2 = -x / (x^2 + y^2)^(3/2)
        // d^2y/dt^2 = -y / (x^2 + y^2)^(3/2)
        // Convert to first-order system:
        // y[0] = x, y[1] = x', y[2] = y, y[3] = y'
        // yDot[0] = y[1]
        // yDot[1] = -y[0] / (y[0]^2 + y[2]^2)^(3/2)
        // yDot[2] = y[3]
        // yDot[3] = -y[2] / (y[0]^2 + y[2]^2)^(3/2)
        FirstOrderDifferentialEquations equations = new FirstOrderDifferentialEquations() {
            @Override
            public int getDimension() {
                return 4;
            }

            @Override
            public void computeDerivatives(double t, double[] y, double[] yDot) throws DerivativeException {
                double r2 = y[0] * y[0] + y[2] * y[2];
                double r3 = r2 * Math.sqrt(r2);
                yDot[0] = y[1];
                yDot[1] = -y[0] / r3;
                yDot[2] = y[3];
                yDot[3] = -y[2] / r3;
            }
        };

        double[] y0 = {1.0, 0.0, 0.0, 1.0}; // Initial position (1,0), velocity (0,1) -> circular orbit
        double t0 = 0.0;
        double t = 2.0 * Math.PI; // One full orbit for circular path
        double[] y = new double[4];

        EmbeddedRungeKuttaIntegrator integrator = new DormandPrince54Integrator(1e-6, 1.0, 1e-8, 1e-8);
        integrator.addStepHandler(new StepHandler() {
            @Override
            public void handleStep(org.apache.commons.math.ode.sampling.StepInterpolator interpolator, boolean isLast) throws DerivativeException {
            }
            @Override
            public void reset() {}
            @Override
            public boolean requiresDenseOutput() { return false; }
        });

        double stopTime = integrator.integrate(equations, t0, y0, t, y);

        // For a circular orbit starting at (1,0) with velocity (0,1), after 2*PI time, it should return to (1,0) with velocity (0,1).
        // The magnitude of velocity should remain constant.
        // Energy = 0.5 * (vx^2 + vy^2) - 1/r. Should be conserved.
        // Initial energy: 0.5 * (0^2 + 1^2) - 1/1 = 0.5 - 1 = -0.5
        assertEquals(t, stopTime, 1e-4); // Allow for some integration error
        assertEquals(y0[0], y[0], 1e-4);
        assertEquals(y0[1], y[1], 1e-4);
        assertEquals(y0[2], y[2], 1e-4);
        assertEquals(y0[3], y[3], 1e-4);
        // Check energy conservation
        double finalEnergy = 0.5 * (y[1]*y[1] + y[3]*y[3]) - 1.0 / Math.sqrt(y[0]*y[0] + y[2]*y[2]);
        assertEquals(-0.5, finalEnergy, 1e-4);
    }

