    @Test
    public void testIntegrateWithEvent() throws Exception {
        // Test integration with an event handler that stops the integration
        FirstOrderDifferentialEquations equations = new FirstOrderDifferentialEquations() {
            @Override
            public int getDimension() {
                return 1;
            }

            @Override
            public void computeDerivatives(double t, double[] y, double[] yDot) throws DerivativeException {
                yDot[0] = 1.0; // Simple constant derivative
            }
        };
        double[] y0 = {0.0};
        double t0 = 0.0;
        double t = 10.0; // Target end time
        double[] y = new double[1];

        EmbeddedRungeKuttaIntegrator integrator = new DormandPrince54Integrator(1e-6, 1.0, 1e-6, 1e-6);

        // Event: stop when y reaches 5.0
        integrator.addEventHandler(new EventHandler() {
            @Override
            public void reset() {}
            @Override
            public double g(double t, double[] y) throws DerivativeException {
                return y[0] - 5.0; // Event when y[0] = 5.0
            }
            @Override
            public Action eventOccurred(double t, double[] y, boolean increasing) throws DerivativeException {
                return Action.STOP; // Stop integration when event occurs
            }
        }, 0.1, 1e-6, 100);

        double stopTime = integrator.integrate(equations, t0, y0, t, y);

        // With y' = 1, y(0) = 0, y(t) = t. The event should occur at t=5.0.
        assertEquals(5.0, stopTime, 1e-5);
        assertEquals(5.0, y[0], 1e-5);
    }

    @Test
    public void testIntegrateWithEventAndRecompute() throws Exception {
        // Test integration with an event handler that resets derivatives
        FirstOrderDifferentialEquations equations = new FirstOrderDifferentialEquations() {
            @Override
            public int getDimension() {
                return 1;
            }

            @Override
            public void computeDerivatives(double t, double[] y, double[] yDot) throws DerivativeException {
                yDot[0] = t > 5.0 ? -1.0 : 1.0; // Change behavior after t=5.0
            }
        };
        double[] y0 = {0.0};
        double t0 = 0.0;
        double t = 10.0;
        double[] y = new double[1];

        EmbeddedRungeKuttaIntegrator integrator = new DormandPrince54Integrator(1e-6, 1.0, 1e-6, 1e-6);

        // Event: when y[0] reaches 5.0, reset state (not really needed here, but tests the mechanism)
        integrator.addEventHandler(new EventHandler() {
            @Override
            public void reset() {}
            @Override
            public double g(double t, double[] y) throws DerivativeException {
                return y[0] - 5.0;
            }
            @Override
            public Action eventOccurred(double t, double[] y, boolean increasing) throws DerivativeException {
                // If we were to change initial conditions or something, we'd do it here.
                // For this test, we just ensure the derivatives are recomputed.
                return Action.RESET_DERIVATIVES;
            }
        }, 0.1, 1e-6, 100);

        double stopTime = integrator.integrate(equations, t0, y0, t, y);

        // Expected behavior:
        // From t=0 to t=5, y(t) = t, so y(5) = 5.0
        // From t=5 to t=10, y'(t) = -1.
        // At t=5, y=5.0. So for t>5, y(t) = 5.0 - (t - 5.0) = 10.0 - t
        // At t=10, y(10) = 10.0 - 10.0 = 0.0
        assertEquals(t, stopTime, 1e-4);
        assertEquals(0.0, y[0], 1e-4);
    }


