    @Test
    public void testSetMinReductionEdgeCases() {
        EmbeddedRungeKuttaIntegrator integrator = new DormandPrince54Integrator(1e-6, 1.0, 1e-6, 1e-6);
        // Minimal reduction factor must be positive and less than or equal to 1.0
        integrator.setMinReduction(0.1);
        assertEquals(0.1, integrator.getMinReduction(), 1e-9);
        integrator.setMinReduction(1.0);
        assertEquals(1.0, integrator.getMinReduction(), 1e-9);
        // Values outside [0, 1] are not explicitly checked in the constructor,
        // but the typical usage implies these bounds. The integrate method uses
        // Math.max(minReduction, ...) so negative values would be clamped to 0.
        // Values > 1 would be clamped by Math.min(maxGrowth, ...) if maxGrowth < 1,
        // otherwise they would be used directly.
        // For the purpose of this test, we focus on valid ranges.
    }

